#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NAME_LEN 51

typedef struct {
    char name[MAX_NAME_LEN];
    int hot;
} Project;

Project *new_Project(char *name, int hot) {
    Project *p = (Project *) malloc(sizeof(Project));
    strcpy(p->name, name);
    p->hot = hot;
    return p;
}

char *lower(char *s) {
    char *res = (char *) calloc(MAX_NAME_LEN, sizeof(char));
    strcpy(res, s);

    int diff = 'a' - 'A';

    int i = 0;
    while (res[i] != '\0') {
        if (res[i] >= 'A' && res[i] <= 'Z') {
            res[i] = (char) (res[i] + diff);
        }
        i++;
    }

    return res;
}

int cmp(const void *a, const void *b) {
    Project *A = *((Project **) a);
    Project *B = *((Project **) b);

    if (A->hot != B->hot) {
        return B->hot - A->hot;
    } else {
        return strcmp(lower(A->name), lower(B->name));
    }
}

int main() {
    int n;
    scanf("%d", &n);

    int weights[5];
    for (int i = 0; i < 5; i++) {
        scanf("%d", &weights[i]);
    }

    Project *ps[n];

    for (int i = 0; i < n; i++) {
        char name[MAX_NAME_LEN];
        scanf("%s", name);

        int hot = 0;
        for (int j = 0; j < 5; j++) {
            int val;
            scanf("%d", &val);

            hot += val * weights[j];
        }

        ps[i] = new_Project(name, hot);
    }

    qsort(ps, n, sizeof(Project *), cmp);

    for (int i = 0; i < n; i++) {
        puts(ps[i]->name);
    }

    return 0;
}
